<script setup lang="ts">
import{ref}from'vue';import{locale}from'../../i18n';import WorkspaceIcon from'../../components/WorkspaceIcon.vue';
const props=defineProps<{security:{required:boolean;version:number}}>();const version=ref(props.security.version),password=ref(''),code=ref(''),secret=ref(''),busy=ref(false),error=ref(''),notice=ref('');const tr=(a:string,b:string)=>locale.value==='id'?a:b;
async function command(action:string){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const r=await fetch('/pos/business/security',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??''},body:JSON.stringify({action,password:password.value,code:code.value,version:version.value}),signal:AbortSignal.timeout(20000)});const v=await r.json();if(!r.ok)throw Error(v.code??'SECURITY_OPERATION_FAILED');if(v.redirect){location.replace(v.redirect);return;}if(v.secret){secret.value=v.secret;version.value=v.version;}else notice.value=tr('Identitas diverifikasi. Tindakan administrasi tersedia selama 5 menit.','Identity verified. Administration is available for 5 minutes.');}catch(e){error.value=tr('Belum berhasil. Periksa kata sandi dan kode, lalu muat ulang jika pengaturan sudah berubah.','Unable to complete. Check password/code and reload if settings changed.')+' · '+String(e);}finally{password.value='';code.value='';busy.value=false;}}
</script>
<template><main class="security-card"><span class="badge"><WorkspaceIcon name="shield-check"/>{{tr('KEAMANAN AKUN BISNIS','BUSINESS ACCOUNT SECURITY')}}</span><h1>{{tr('Anda mengendalikan keamanan akun.','You control your account security.')}}</h1><p>{{tr('Authenticator menambahkan lapisan verifikasi saat masuk. Perubahan membutuhkan kata sandi dan, jika aktif, kode authenticator. Sesi lama akan dicabut setelah perubahan.','An authenticator adds sign-in verification. Changes require your password and, when enabled, an authenticator code. Existing sessions are revoked after changes.')}}</p><p class="status">{{security.required?tr('TOTP diwajibkan untuk akun Anda','TOTP is required for your account'):tr('TOTP dinonaktifkan pada akun Anda','TOTP is disabled for your account')}}</p><form @submit.prevent="command(secret?'confirm':security.required?'disable':'enable')"><fieldset :disabled="busy"><label>{{tr('Kata sandi saat ini','Current password')}}<input v-model="password" type="password" required maxlength="72" autocomplete="current-password"/></label><div v-if="secret" class="secret"><p>{{tr('Tambahkan kunci ini ke aplikasi authenticator. Jangan bagikan kepada siapa pun.','Add this key to your authenticator. Never share it.')}}</p><code>{{secret}}</code></div><label v-if="security.required||secret">{{tr('Kode authenticator 6 digit','6-digit authenticator code')}}<input v-model="code" type="text" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" :required="!!secret"/></label><button type="submit">{{busy?tr('Memproses…','Processing…'):secret?tr('Konfirmasi TOTP','Confirm TOTP'):security.required?tr('Nonaktifkan TOTP','Disable TOTP'):tr('Aktifkan TOTP','Enable TOTP')}}</button><button v-if="!security.required&&!secret" type="button" @click="command('reauth')" :disabled="!password">{{tr('Verifikasi kata sandi untuk administrasi','Verify password for administration')}}</button></fieldset></form><p v-if="error" role="alert">{{error}}</p><p role="status">{{notice}}</p><p>{{tr('Pengaturan ini hanya untuk akun pemilik bisnis Anda. Keamanan pemilik platform tetap wajib.','This setting applies only to your business owner account. Platform owner security remains mandatory.')}}</p></main></template>
<style scoped>.security-card{max-width:760px;padding:28px;background:#FFFFFF;border:1px solid #E9EBFF;border-radius:24px;box-shadow:0 12px 36px #1B1B3914;color:#1B1B39;font:16px/1.7 system-ui}.badge{display:flex;gap:10px;color:#3965FA;font-size:14px;font-weight:700}.security-card h1{font-size:28px;line-height:1.3}.security-card fieldset{border:0;padding:0}.security-card label{display:grid;gap:8px;margin:20px 0}.security-card input{padding:12px;font:inherit;border:1px solid #99B7FC;border-radius:10px}.security-card button{padding:13px 18px;background:#3965FA;color:#FFFFFF;border:0;border-radius:10px;font:600 16px system-ui;margin:8px 12px 8px 0}.status,.secret{padding:16px;background:#E9EBFF;border-radius:12px}.secret code{overflow-wrap:anywhere}.security-card button:disabled{opacity:.5}</style>
